"use strict";
(()=>{
const pages=[['00-state','兩張初始資料卡'],['second-order','放手後怎麼回來'],['forced','一邊推，一邊擺'],['rlc','電壓越過了目標'],['complex','箭頭轉四分之一圈'],['phasors','同頻率，一起轉'],['laplace','把變化換成乘法'],['initial-values','把起跑資料帶過去'],['transfer','輸入到輸出的規則'],['convolution','小推力累積成回應'],['fourier-series','週期波形的配方'],['fourier-transform','一個脈衝的頻譜'],['pde','一根棒子很多位置'],['separation','把時空拆開看'],['boundaries','邊界替答案定形'],['engineering','回到工程，選工具']];
const current=document.body.dataset.page||'index';
const header=document.getElementById('site-header');if(header)header.innerHTML='<a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">∿</span>圖解工程數學</a><nav class="header-links" aria-label="網站連結"><a class="wide-link" href="index.html#learning-path">學習地圖</a><a href="glossary.html">小字典</a><a href="sources.html">資料來源</a></nav>';
const nav=document.getElementById('course-nav');if(nav){let links='<p class="nav-label">從變化，到工具</p><ul class="course-links"><li><a href="index.html"'+(current==='index'?' aria-current="page"':'')+'><span class="nav-num">⌂</span>課程地圖</a></li>';pages.forEach((p,i)=>{links+='<li><a href="'+p[0]+'.html"'+(current===p[0]?' aria-current="page"':'')+'><span class="nav-num">'+String(i).padStart(2,'0')+'</span>'+p[1]+'</a></li>'});nav.innerHTML='<details class="course-menu"><summary>章節導覽 · 隨時換一頁</summary>'+links+'</ul><p class="nav-note">先跟著同一個例子看幾步，<br>再把其中一個數字改一改。<br>不用作答，也不必記進度。</p></details>';}
const menu=document.querySelector('.course-menu');if(menu){const media=matchMedia('(min-width:1051px)');menu.open=media.matches;media.addEventListener('change',e=>{menu.open=e.matches;});}
const footer=document.getElementById('site-footer');if(footer)footer.innerHTML='<div class="footer-inner"><span>圖解工程數學 · 原創圖解與可離線操作的實驗</span><span><a href="00-state.html">零基礎入口</a> · <a href="glossary.html">查一個詞</a> · <a href="sources.html">模型與來源</a></span></div>';
const NS='http://www.w3.org/2000/svg';
const $=id=>document.getElementById(id);
function svg(tag,attrs={},txt){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,String(v)));if(txt!==undefined)e.textContent=txt;return e;}
function fmt(n,d=3){if(!Number.isFinite(n))return '此條件不適用';return Math.abs(n)<1e-10?'0':String(Number(n.toFixed(d)));}
function text(id,t){const e=$(id);if(e)e.textContent=t;}
function range(id){const e=$(id);return e?Number(e.value):0;}
function init(ids,render){if(!$('drawing'))return;const controls=ids.map($).filter(Boolean);const defaults=controls.map(e=>e.value);function update(){controls.forEach(e=>text(e.id+'-value',e.tagName==='SELECT'?e.options[e.selectedIndex].text:fmt(+e.value)));render();}controls.forEach(e=>{e.addEventListener('input',update);e.addEventListener('change',update)});const reset=$('reset');if(reset)reset.addEventListener('click',()=>{controls.forEach((e,i)=>e.value=defaults[i]);update()});update();}
function plot(group,series,{xMin=0,xMax=6,yMin=-1.5,yMax=1.5,xLabel='時間 t（s）',yLabel='位置 x（m）',width=660,height=360}={}){if(!group)return;group.replaceChildren();const L=65,R=25,T=42,B=53,w=width-L-R,h=height-T-B;const X=x=>L+(x-xMin)/(xMax-xMin)*w,Y=y=>T+(yMax-y)/(yMax-yMin)*h;for(let i=0;i<=4;i++){let x=xMin+(xMax-xMin)*i/4,y=yMin+(yMax-yMin)*i/4;group.append(svg('line',{x1:X(x),y1:T,x2:X(x),y2:T+h,class:'gridline'}),svg('text',{x:X(x),y:T+h+22,'text-anchor':'middle',class:'svg-small'},fmt(x,2)),svg('line',{x1:L,y1:Y(y),x2:L+w,y2:Y(y),class:'gridline'}),svg('text',{x:L-10,y:Y(y)+5,'text-anchor':'end',class:'svg-small'},fmt(y,2)));}group.append(svg('path',{d:`M ${L} ${T} V ${T+h} H ${L+w}`,class:'axis'}),svg('text',{x:L,y:23,class:'svg-label'},yLabel),svg('text',{x:L+w,y:height-9,'text-anchor':'end',class:'svg-small'},xLabel));if(yMin<0&&yMax>0)group.append(svg('line',{x1:L,y1:Y(0),x2:L+w,y2:Y(0),class:'axis'}));series.forEach((s,i)=>{const values=s.points||Array.from({length:401},(_,j)=>{const x=xMin+(xMax-xMin)*j/400;return[x,s.fn(x)]});let path='';values.forEach(([x,y],j)=>{if(Number.isFinite(y))path+=(j?'L':'M')+X(x).toFixed(2)+' '+Y(Math.max(yMin,Math.min(yMax,y))).toFixed(2)+' ';});group.append(svg('path',{d:path,fill:'none',stroke:s.color||['#345cdf','#cf604b','#172a45'][i%3],'stroke-width':s.width||3,'stroke-dasharray':s.dash||'','stroke-linejoin':'round'}));});return {X,Y,svg};}
function homogeneous(b,x0,v0,t,k=4,m=1){const a=b/(2*m),D=a*a-k/m;let x,v;if(Math.abs(D)<1e-10){const c=v0+a*x0,e=Math.exp(-a*t);x=e*(x0+c*t);v=e*(c-a*(x0+c*t));}else if(D<0){const w=Math.sqrt(-D),c=(v0+a*x0)/w,e=Math.exp(-a*t),co=Math.cos(w*t),si=Math.sin(w*t);x=e*(x0*co+c*si);v=e*((c*w-a*x0)*co+(-x0*w-a*c)*si);}else{const q=Math.sqrt(D),r1=-a+q,r2=-a-q,c1=(v0-r2*x0)/(r1-r2),c2=x0-c1;x=c1*Math.exp(r1*t)+c2*Math.exp(r2*t);v=r1*c1*Math.exp(r1*t)+r2*c2*Math.exp(r2*t);}return{x,v};}
window.Lab={$: $,svg,fmt,text,range,init,plot,homogeneous,pages};
})();
